/**
 * M16: types for Shape, the part of Product Studio before epics (skills/product-studio/scripts/shape.py and
 * shape_route.py). Derived from the real engine output in web/fixtures (idea.*, brief.*, case.*, verdict.*,
 * lookback.*, status.ideas*, refresh.ideas*), generated by web/fixtures/product_memory.py. The Operations table in
 * types.ts names these; the fixture imports in the Product Studio app check each file against them at compile time.
 *
 * These types describe; they never decide. The engine names every stage, verdict view, route and next step. The app
 * never scores an idea and never recommends a verdict.
 */

/** The five places an idea can be. Shown to the person as `stage_words`. */
export type IdeaStage = "new" | "exploring" | "brief" | "decided" | "shaped";
export type VerdictDecision = "go" | "not-now" | "no";
/** M18 adds "small-change": one outcome in one capability, at most one shipped rule, nothing in a high-risk area. */
export type ShapeRoute = "small-change" | "one-slice" | "epic" | "several-epics";
export type OutcomeResult = "met" | "not-met" | "too-early";
export type AssumptionResult = "confirmed" | "wrong" | "unknown";
export type LookbackResult = OutcomeResult | AssumptionResult;
/** typed by the PM, an idea-template issue, a request issue, a fault from production, or a change to a shipped rule. */
export type IdeaSourceKind = "typed" | "idea" | "request" | "fault" | "change";

/**
 * What the engine says to do next for one idea (`next.kind`). The engine has no next-action kind for Shape in
 * `status.next_actions`; each idea carries its own. Unknown kinds are still shown, by their sentence.
 */
export type IdeaNextKind =
  | "explore"
  | "write_brief"
  | "check_brief"
  | "record_verdict"
  | "publish"
  | "renumber"
  | "size"
  | "map"
  | "settle"
  | "apply"
  | "look_back"
  | "none"
  | (string & {});

/** Where an idea came from: identifiers only, never the issue's text. */
export interface IdeaSourceIds {
  kind: IdeaSourceKind | (string & {});
  /** A request or idea-template issue's number. */
  number?: number;
  /** A fault's ticket (AUTO-...). */
  ticket?: string;
  /** For a change: the shipped rule it starts from (SLICE-NNN/FR-NN). */
  rule?: string;
}

/** A verdict as it stands against the brief now. `stale`: the brief changed after it was recorded. */
export interface IdeaVerdict {
  decision: VerdictDecision | (string & {});
  /** The signed-in GitHub login of whoever recorded it; null when nobody was signed in. */
  by: string | null;
  at: string;
  revision: number;
  holds: boolean;
  stale: boolean;
  /** The person's reason, their words: bounded to one line of at most 500 characters on a board row. */
  reason?: string;
  /** The brief the verdict was recorded on; null for a Not now or No given before any brief. */
  brief_sha256?: string | null;
  /** Why it no longer holds, in plain words; only when stale. */
  stale_note?: string;
}

/** Where the idea is saved, from Studio's own records and the last read of GitHub (no network). */
export interface IdeaGithubView {
  saved: "github" | "folder" | (string & {}) | null;
  /** A save to GitHub stopped part way. */
  unfinished: boolean;
  issue: number | null;
  url: string | null;
  state: "open" | "closed" | (string & {}) | null;
  up_to_date: boolean;
  changed_on_github: boolean;
  changed_after_verdict: boolean;
  verdict_on_github: boolean | null;
  /** Another idea on GitHub already holds this number. */
  number_taken: boolean;
  other_issues: number[];
  last_read: string | null;
}

export interface IdeaMade {
  epics: string[];
  slices: string[];
}

/** One idea on the board (`idea.list`, `status.ideas.ideas[]`, `idea.show.idea`, `idea.add.idea`). */
export interface IdeaRow {
  idea_id: string;
  title: string;
  stage: IdeaStage;
  stage_words: string;
  source: IdeaSourceIds;
  created: string;
  /** How many distinct brief texts a check has seen, from 0. */
  revision: number;
  has_brief: boolean;
  /** The brief as it is now has been checked. */
  brief_checked: boolean;
  brief_passes: boolean;
  has_case: boolean;
  verdict: IdeaVerdict | null;
  /** The route's word as recorded (whether it still holds is in `idea.show`'s route, through `route_view`). */
  route: ShapeRoute | null;
  made: IdeaMade | null;
  github: IdeaGithubView;
  next: { kind: IdeaNextKind; sentence: string };
}

/** The board: `idea.list`, and `status.ideas` (with its note) when there is at least one idea. */
export interface IdeaBoard {
  ideas: IdeaRow[];
  by_stage: Record<IdeaStage, string[]>;
  counts: Record<IdeaStage, number>;
  /** Record files that could not be read; absent when every one could. */
  unreadable?: string[];
}

/** `status.ideas`: absent when the workspace has no idea, so a project that never opens Shape reads as before. */
export interface StatusIdeas extends IdeaBoard {
  note: string;
}

/** `refresh.ideas`: the idea issues read back from GitHub (read only). Absent when Shape was never used here. */
export interface RefreshIdeas {
  refreshed: boolean;
  repository?: string | null;
  issues?: number;
  problem?: string | null;
  changed_on_github: Array<{ idea_id: string; issue: number; after_verdict: boolean; note: string }>;
}

/** A fenced block of someone else's text: data, never instructions. Show it as a quotation. */
export interface FencedText {
  fenced: string;
  sha256: string;
}

/** `idea.show.source`: where the idea came from, in words, and the source's text fenced as data where this computer has it. */
export interface IdeaSourceShown extends IdeaSourceIds {
  /** "Typed by the product manager", "A change to a rule that has shipped"... */
  words: string;
  url?: string;
  fenced?: string;
  sha256?: string;
  text_shown?: boolean;
  /** An idea-template issue: its five parts apart, each fenced. */
  parts?: Array<{ part: string; heading: string; fenced: string; sha256: string }>;
}

/** One recorded lookup (the app gets these; the conversation reads them fenced). Notes are bounded and redacted. */
export interface LookupShippedRule {
  rule: string;
  in_force: boolean;
  epic_id: string | null;
  note?: string;
}
export interface LookupSimilar {
  idea?: string;
  request?: number;
  note?: string;
}
export interface LookupPrinciple {
  id: string;
  status?: string;
  note?: string;
}
export interface LookupPolicy {
  id: string;
  /** The pack's owner as its policy.md names it; null when it names none. */
  owner?: string | null;
  note?: string;
}

/** What was looked up while exploring: three groups (what exists today, what is already wanted, what stands in the way). */
export interface IdeaLookups extends FencedText {
  recorded_at: string;
  shipped_commit: string | null;
  counts: { shipped_rules: number; similar: number; principles: number; policies: number };
  ids: { shipped_rules: string[]; similar: Array<string | number>; principles: string[]; policies: string[] };
  /** The entries in their groups; the app's form only (the terminal gets them fenced). */
  items?: { shipped_rules: LookupShippedRule[]; similar: LookupSimilar[]; principles: LookupPrinciple[]; policies: LookupPolicy[] };
}

/** One look-back result. `comment` says whether it reached the idea's issue. */
export interface LookbackEntry {
  result: LookbackResult | (string & {});
  note: string;
  by: string | null;
  at: string;
  comment?: { posted: boolean; issue?: number; why?: "not_on_github" | "github_not_here" | "already_there" | (string & {}); by?: string };
}

export interface IdeaLookbackRecord {
  outcomes?: Record<string, LookbackEntry>;
  assumptions?: Record<string, LookbackEntry>;
}

/** What the engine counted for the route; `high_risk_areas` is null when it could not be determined. */
export interface RouteCounted {
  outcomes: number;
  capabilities: number;
  shipped_rules: number;
  shipped_rules_looked_up: number;
  high_risk_areas: number | null;
  high_risk_not_determined: string[];
  principle_concerns: number;
  policy_concerns: number;
}

/** The details behind each count, kept with the route (identifiers only), so they can be shown again after a reload. */
export interface RouteDetails {
  touches: { outcomes: string[]; capabilities: string[]; shipped_rules: string[] };
  high_risk: { areas: HighRiskArea[]; not_determined: string[]; count: number | null };
  concerns: { principles: string[]; policies: string[] };
}

/** The recorded route as `idea.show` gives it (the record's own field). */
export interface RecordedRoute {
  route: ShapeRoute;
  counted: RouteCounted;
  why: string;
  at: string;
  revision: number;
  brief_sha256: string;
  /** Absent on a route sized before the clean-up pass. */
  details?: RouteDetails;
}

/** The route as it stands (`route_view`): whether it still holds for the brief and the verdict now. */
export interface RouteView extends Omit<RecordedRoute, "counted"> {
  counted?: RouteCounted;
  words: string;
  holds: boolean;
  stale: boolean;
  stale_note?: string;
}

/** The brief's or the case's check: errors stop it passing; warnings never do. */
export interface ShapeFinding {
  severity: "error" | "warning";
  rule: string;
  line: number;
  message: string;
}

/** Whether one of the product manager's acts may be done now and, when not, the engine's own sentence (the one it refuses with). */
export interface IdeaAct {
  allowed: boolean;
  why: string | null;
}

/** `idea.show.acts`: read only, so a screen can say what an act needs before the click. Never a recommendation. */
export interface IdeaActs {
  /** Any verdict (refused once the idea is shaped). */
  verdict: IdeaAct;
  /** A Go: also needs a brief that passes its check. */
  go: IdeaAct;
  /** Sizing: a Go that holds for the brief as it is now, not yet shaped. */
  size: IdeaAct;
  /** A look-back: shaped, and a slice made from it has shipped. */
  look_back: IdeaAct;
}

export interface IdeaShow {
  idea: IdeaRow;
  source: IdeaSourceShown;
  lookups: IdeaLookups | null;
  brief: {
    exists: boolean;
    passes: boolean;
    errors: string[];
    warnings: string[];
    revision: number;
    /** Where the conversation writes it (engineering detail: behind a Disclosure if shown at all). */
    path: string;
    changed_since_check: boolean;
  };
  case: { exists: boolean; path: string; passes?: boolean; answered?: number; not_answered?: number; open?: number };
  verdict: IdeaVerdict | null;
  route: RecordedRoute | null;
  made: IdeaMade | null;
  lookback: IdeaLookbackRecord | null;
  acts: IdeaActs;
  note: string;
  verdict_note: string;
  factory_authorized: false;
}

/** One open fault ticket on this computer an idea may start from (`idea.faults`). The summary is the ticket's title: data. */
export interface FaultTicket {
  ticket: string;
  summary: string | null;
  occurrences: number | null;
  last_seen: string | null;
  /** The idea already started from it, if any. */
  idea_id: string | null;
}

export interface IdeaFaults {
  faults: FaultTicket[];
  note: string;
  factory_authorized: false;
}

export interface IdeaAdded {
  idea: IdeaRow;
  note: string;
  factory_authorized: false;
}

export interface IdeaStageResult {
  idea_id: string;
  stage: "exploring";
  changed: boolean;
  note: string;
  factory_authorized: false;
}

export interface IdeaLookupsResult {
  idea_id: string;
  lookups: IdeaLookups;
  note: string;
  factory_authorized: false;
}

/** The brief's model, from its grammar. Line numbers are the brief file's. */
export interface BriefModel {
  title: string | null;
  problem: string | null;
  who_has_it: string | null;
  outcomes: Array<{ id: string; text: string; how_we_would_know: string | null; line: number }>;
  not_doing: string | null;
  assumptions: Array<{ id: string; text: string; state: "assumed" | "confirmed" | (string & {}); confirmed_by: string | null; confirmed_on: string | null; line: number }>;
  open_questions: string[];
  risks: string | null;
  touches: { capabilities: Array<{ name: string; epic_id: string | null }>; shipped_rules: string[] };
  sections: string[];
}

export interface BriefShow {
  idea_id: string;
  revision: number;
  changed_since_check: boolean;
  sha256: string;
  /** The brief as written: render it as text, never as markup. */
  text: string;
  model: BriefModel;
  passes: boolean;
  findings: ShapeFinding[];
  verdict: IdeaVerdict | null;
  factory_authorized: false;
}

export interface BriefCheck {
  idea_id: string;
  revision: number;
  new_revision: boolean;
  stage: IdeaStage;
  passes: boolean;
  errors: string[];
  warnings: string[];
  findings: ShapeFinding[];
  counts: { outcomes: number; assumptions: number; open_questions: number; shipped_rules: number; capabilities: number };
  verdict: IdeaVerdict | null;
  note: string;
  factory_authorized: false;
}

export interface CaseModel {
  title: string | null;
  /** "As the customer would hear it", on one line. */
  customer: string | null;
  customer_sentences: number;
  questions: Array<{ id: string; question: string; state: "answered" | "not_answered" | null; answer: string | null; line: number }>;
  answered: number;
  not_answered: number;
  open: number;
}

/** `case.check`; `case.show` adds the text. */
export interface CaseCheck {
  idea_id: string;
  model: CaseModel;
  passes: boolean;
  errors: string[];
  warnings: string[];
  findings: ShapeFinding[];
  verdict_note: string;
  factory_authorized: false;
}

export interface CaseShow extends CaseCheck {
  text: string;
}

export interface VerdictRecorded {
  idea_id: string;
  verdict: IdeaVerdict;
  /** The verdict this one replaced, as it was recorded. */
  replaced: (Omit<IdeaVerdict, "holds" | "stale"> & { reason: string }) | null;
  stage: "decided";
  recorded_without_github: boolean;
  /** Why no login was recorded, in plain words. */
  why_no_login?: string;
  note: string;
  factory_authorized: false;
}

export type IdeaPublished =
  | {
      published: true;
      saved_to: "github";
      issue: number;
      url: string;
      revision: number;
      state_label: string;
      verdict_posted: boolean;
      by: string;
      note: string;
      factory_authorized: false;
    }
  | { published: true; saved_to: "folder"; folder: string; why_folder: string; revision: number; state_label: string; note: string; factory_authorized: false };

export interface IdeaRenumbered {
  renumbered: { from: string; to: string };
  factory_authorized: false;
}

export interface HighRiskArea {
  /** The scan rule's reason, in words. */
  area: string;
  rules: string[];
  files: string[];
  file_count: number;
}

export interface IdeaSized {
  idea_id: string;
  route: ShapeRoute;
  route_words: string;
  why: string;
  counted: RouteCounted;
  touches: { outcomes: string[]; capabilities: string[]; shipped_rules: string[] };
  high_risk: { basis: string; areas: HighRiskArea[]; not_determined: string[]; count: number | null; not_determined_note?: string };
  concerns: { principles: string[]; policies: string[] };
  /** The fixed rule, in words. */
  rule: string;
  note: string;
  factory_authorized: false;
}

export interface ShapeMapSlice {
  key: string;
  title: string;
  scope: string;
  /** A map epic's key, or an existing EPIC-NNN. */
  epic: string;
  depends_on: string[];
  outcomes: string[];
  /** Line ranges of the brief, such as "9-10". */
  cites: string;
  /** Set once applied. */
  slice_id: string | null;
  status: string | null;
}

export interface ShapeSettlement {
  as: "slice" | "out-of-scope" | "later";
  slice?: string;
  reason?: string;
  at: string;
}

export interface ShapeCoverageRow {
  outcome: string;
  carried_by: string[];
  state: "covered" | "settled" | "not_covered" | (string & {});
  settled?: ShapeSettlement;
}

/** `idea.map-status`, and the base of map, settle and apply. */
export interface ShapeMapStatus {
  idea_id: string;
  stage: IdeaStage;
  /** Null when the idea has not been sized. */
  route: RouteView | null;
  map: {
    revision: number;
    route: ShapeRoute;
    epics: Array<{ key: string; title: string; criteria: string[] }>;
    slices: ShapeMapSlice[];
    applied: boolean;
    mapped_at: string;
  } | null;
  /** Absent when there is no map yet (then `map` is null). */
  coverage?: ShapeCoverageRow[];
  not_covered?: string[];
  /** Why the map cannot be applied now (the brief or the route changed), in plain words. Absent when there is no map. */
  blockers?: string[];
  can_apply: boolean;
  note: string;
  factory_authorized: false;
}

export interface ShapeMapRecorded extends ShapeMapStatus {
  recorded: true;
  settlements_dropped: string[];
}

export interface ShapeSettled extends ShapeMapStatus {
  settled: ShapeSettlement & { outcome: string };
}

export interface ShapeApplied extends ShapeMapStatus {
  applied: boolean;
  made: IdeaMade;
  kept: IdeaMade;
  missing: string[];
  /** M18: present when the apply started a small change, with the kind the product manager gave. */
  small_change?: { change: "fix" | "adjustment"; shipped_rule: string | null };
}

/** The proposed map the conversation writes; `idea.map` checks it. */
export interface ShapeMapInput {
  epics: Array<{ key: string; title: string; criteria: string[] }>;
  slices: Array<{ key: string; title: string; scope: string; epic: string; depends_on: string[]; outcomes: string[]; cites: string[] }>;
}

/** The lookups the conversation records; `idea.lookups` checks every ID, all or nothing. */
export interface IdeaLookupsInput {
  shipped_rules?: Array<{ rule: string; note?: string }>;
  similar?: Array<{ idea: string; note?: string } | { request: number; note?: string }>;
  principles?: Array<{ id: string; note?: string }>;
  policies?: Array<{ id: string; note?: string }>;
}

export interface IdeaChanged {
  idea_id: string;
  rule: string;
  stage: "exploring";
  lookups: IdeaLookups;
  /** Where the starter brief is, in words. */
  brief: string;
  note: string;
  next: string;
  factory_authorized: false;
}

export interface LookbackRecorded {
  idea_id: string;
  item: string;
  result: LookbackResult;
  by: string | null;
  shipped_slices: string[];
  comment: NonNullable<LookbackEntry["comment"]>;
  /** Outcomes and assumptions still without a result. */
  waiting: string[];
  note: string;
  factory_authorized: false;
}

export interface ChainLookback {
  result: LookbackResult | (string & {});
  note: string;
  by: string | null;
  at: string;
}

/** `idea.chain`: reads only. Every missing value is null with a sentence under `missing`. */
export interface IdeaChain {
  idea_id: string;
  title: string;
  stage: IdeaStage;
  route: Omit<RouteView, "counted"> | null;
  made: IdeaMade | null;
  outcomes: Array<{
    outcome: string;
    text: string | null;
    how_we_would_know: string | null;
    in_brief: boolean;
    slices: string[];
    settled: ShapeSettlement | null;
    lookback: ChainLookback | null;
    missing: string[];
  }>;
  assumptions: Array<{ assumption: string; text: string; state: string; lookback: ChainLookback | null; missing: string[] }>;
  slices: Array<{
    slice_id: string;
    title?: string;
    epic_id?: string;
    outcomes?: string[];
    spec?: { invariants: string[]; functional_requirements: string[]; matrix_rules: string[]; scenarios: string[] } | null;
    progress?: string;
    issue?: number | null;
    times?: { marked_ready: string | null; building: string | null; question: string | null; shipped: string | null };
    missing: string[];
  }>;
  epics: Array<{ epic_id: string; acceptance: null; missing: string }>;
  /** Null when the brief is not in this workspace (then `missing` says so). */
  brief: { revision: number; sha256: string | null } | null;
  last_read: string | null;
  missing: string[];
  note: string;
  factory_authorized: false;
}

/** On a slice made from an idea (`slice.show`, `slice.resume`): the outcomes it serves and the brief's earlier words, fenced. */
export interface SliceFromIdea extends FencedText {
  idea_id: string;
  outcomes: string[];
  /** The line its why must carry. */
  why_line: string;
  brief_matches_map: boolean;
  scope: string | null;
  note: string;
  brief_note?: string;
}

/** On a work order or an epic made by `idea.apply`: identifiers only. */
export interface Serves {
  idea: string;
  outcomes: string[];
}
